INSERT INTO feature VALUES('std-io','modules','The standard streams','packages','implemented','uncommon','mainstream languages','`std.io`''s `print` and `eprint` write one line to standard output and standard error, and `read_line` reads one from standard input with its newline, the empty string at its end, each through the console''s root capability, which `std.authority`''s `console` opens from the authority `main` is handed; `write_bytes` writes a list of `u8` to standard output with no newline, and `read_bytes` makes one read of at most a count of bytes from the input that `read_line` reads; a program reaches the streams through a capability it was given and never through the ambient interfaces, each stream a host interface of its own.','surface-dispatcher surface-driver surface-evaluate core-term','library/std/src/io.gandr corpus/model/effects/hello.gandr corpus/model/console/answer.gandr crates/surface-driver/tests/cli.rs::a_program_reads_and_answers_on_the_standard_streams_2970 crates/surface-evaluate/src/evaluate/entry/tests.rs::an_entry_reads_and_writes_bytes','corpus/ledger/features/std-io.gandr',NULL);
